from pathlib import Path
import csv,json,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
out=Path('tmp/merchant_liquidity_player_20260921')
x=json.loads((out/'analysis.json').read_text())
rows=list(csv.DictReader((out/'merchant_daily.csv').open(encoding='utf-8-sig')))
fig,axs=plt.subplots(2,2,figsize=(11,6),sharex=True)
for ax,(c,z) in zip(axs.flat,x['cells'].items()):
 r=[a for a in rows if a['cell']==c];ds=[int(a['day']) for a in r]
 ax.plot(ds,[int(a['merchant_cash'])/10000 for a in r],label='Cash',lw=1)
 ax.plot(ds,[int(a['merchant_economic_assets'])/10000 for a in r],label='Cash + marked inventory',lw=1,alpha=.7)
 ax.set_title('Market '+c);ax.set_yscale('log');ax.set_ylabel('Currency (log scale)');ax.grid(alpha=.2);ax.set_xlabel('Simulation day')
axs[0,0].legend(fontsize=8);fig.suptitle('Merchant liquidity: formal start, seed 20260718, 1,000 days');fig.tight_layout();fig.savefig(out/'merchant_cash.png',dpi=150)
lines=['# 商人资金运行记录（2026-09-21）','','本轮复现了局部商人现金严重萎缩：4 个市场中 3 个曾跌到第 1 天现金的 10% 以下，持续数百天；没有任何一个市场的商人现金恰好归零。不是所有市场共同枯竭，且不是开局立刻下降：前三个受影响市场先积累现金，在第 63–84 天附近见顶，再明显回落。','','## 运行范围','','正式新开局，60×40 地图，seed=20260718，玩家加 3 个外国，起始人口 80，结束人口 110。模拟第 1–1000 天，1,000 个已提交经济周期。沿用当前工作区修复后的 DLL；未修改经济公式、内容或余额。不是用户原存档，也没有人为制造贸易供需。使用玩家入口相同的全图 ACTIVE / 0xFFF 和 economy_auto_pod=true。明细采集 539、691、837、1902 四个起始有人口地块；逐日相加商人现金与全球 summary 完全一致。','','金额以下均按 10,000 子单位 = 1 货币换算；第 1 天是完成结算后的首个记录点，不是结算前初始余额。','','|市场|第1天现金|第1000天现金|最低现金（天）|首次低于首日10%|低于10%的总天数/最长连续天数|','|---|---:|---:|---|---:|---|']
for c,z in x['cells'].items():
 e=z['events']['0.1'];lines.append(f"|{c}|{z['first']/10000:.2f}|{z['last']/10000:.2f}|{z['minimum']/10000:.2f}（{z['minimum_day']}）|{e['first_day'] or '未发生'}|{e['days']} / {e['longest_run']}|")
lines += ['','539 最终比首日下降 97.0%；1902 下降 94.2%；691 虽在末期反弹到 159.95，期间仍有 262 天低于首日现金的 10%，最长连续 232 天。837 最终现金 3,820.26，占全球商人现金的 95.41%。全球现金由 946.97 上升到 4,003.99，不能用这个总额判断每个市场健康。','','## 观察与解释','','- **P1，局部长期流动性紧张，证据充分。** 539、691、1902 分别有 60、32、5 天，期末现金低于当期经营流出；该流出是采购、贸易购买及发放商人信用，不包含全部生活开支。它是一期支出的覆盖指标，不是破产判据。','- **早期存在库存占款，后期不只是现金转成库存。** 539 第 200 天现金 19.78、库存按买入因子估值 662.35；第 1000 天分别只剩 8.10 和 1.65。按此口径的现金加库存资产，从首日 629.13 降到 9.75。库存估值随价格改变，不能当作可立即变现的保证。','- **不能把现金下降全解释为采购亏损。** 539 的商人人口在第 100 天为 7，第 200 天为 1，末日为 8；人口转职会按比例带走/带入资金。第 101–200 天该市场所记录的商人收入 3,248.57、支出 4,637.00，也显示收支压力；但 cohort 流量随人口拆分转移，不能直接充当独立企业账本。','- **本轮没有市场间资金调剂。** 贸易购买、贸易销售现金及贸易订单均为 0。因此 837 的富余现金没有通过本轮贸易流向另外三个市场。不能由此证明贸易代码必然失效。','- **建材修改是否导致本现象尚未证明。** 当前没有相同种子、相同时长的修改前对照；人口职业变化、库存价格与结构、生活消费和采购成本均是竞争解释。本轮结论是症状存在，不是迁移或上轮修复的因果定论。','','## 数据和运行校验','','五张 CSV 总计 695,107 行：summary 1,000，cohorts 13,107，market 536,000，buildings 21,000，resources 124,000。各表覆盖天 1–1000，无日缺口、主键重复、坏列数、空核心标识或越界 epoch；原生 writer completed，捕获与写出数量一致，无限额截断、无回压等待。人口、货币、货物审计误差逐日全部为 0；fatal=false，worker_fault_count=0。商人指标按（epoch, cell）去重，没有按商品重复相加。','','**性能测试没有通过。** 此诊断复用了性能 harness，实际 17.21 权威天/秒，低于其中 50 天/秒门槛，因此进程非零退出；perf.csv 也包含 2,000 行（驱动与权威 tick 混合），不能称为通过标准性能验收。经济 CSV 则已完整写出并单独通过以上数据校验。','','第一轮未启用玩家入口的 auto POD，权威只提交到第 9 天，文件前缀 094322；该轮排除，不拿它充当 1,000 天数据。后续运行显式启用玩家入口的 economy_auto_pod=true，成功提交并记录到第 1000 天。','','## 代码口径','','- `gdext/src/economy_runtime.h:154`：MONEY_SCALE=10000。','- `gdext/src/economy_csv_recorder.cpp:1376`：本地 merchant_cash 对商人 cohort funds 求和；库存按 stock×price/GOODS_SCALE，再乘买入因子估值。','- `gdext/src/economy_csv_recorder.cpp:837`：全球商人现金、库存、经营流出与流动性覆盖的记录口径。','- `gdext/src/economy_runtime.cpp:11645`：move_cohort_population 按人口比例转移 funds，同时转移本期收入/支出；商人资金并非脱离人口的独立公司账户。','- `Project/project-keynes/scripts/game/player_game.gd:87`：玩家入口开启 economy_auto_pod 和全图权威。','','## 复现和产物','','当前 HEAD：152610e540d808c72c97074c9dc05bce5f05044d，另有工作区未提交修复。debug DLL SHA256：5E3B58CD01C776BAF48437C42262B800649D6AC9B1062CC9C9E033FB3BC35E8D。完整改动快照保存在本目录 runtime_changes.patch；录制脚本保存在 tmp/merchant_probe_headless.gd 和 tmp/merchant_probe_recorder.gd。','','```powershell',"& 'D:/Godot/Godot_v4.6.2-stable_win64.exe/Godot_v4.6.2-stable_win64_console.exe' --headless --path Project/project-keynes --script ../../tmp/merchant_probe_headless.gd -- days=1000 warmup_days=0 speed=50 seed=20260718 width=60 height=40 foreign_count=3 economy_auto_pod=true label=merchant_liquidity_player output_dir=../../tmp/merchant_liquidity_player_20260921",'python .codex/skills/project-keynes-economy-analysis/scripts/profile_economy_record.py --prefix tmp/economy_record_20260921_094552_v25 --repo-root .','python tmp/analyze_merchant_liquidity.py','```','','原始五表共同前缀：`tmp/economy_record_20260921_094552_v25`。原始日志：`tmp/merchant_liquidity_player_20260921.log`。本目录的 `merchant_daily.csv` 是去重后的 4,000 行商人时序，`analysis.json` 为计算结果，`merchant_cash.png` 为轨迹。','','下一步最有区分力的验证是同种子、同权威路径的修改前后 A/B，并对现金骤降日期记录商人转职资金、采购支付、家庭消费、税费和销售回款的独立流水。当前数据足以确认局部资金紧张，不足以给这些原因排序。']
(out/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
